package com.termux.app.workspace;
import java.nio.file.*;import java.util.*;import java.security.*;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public class RetiredDictationCacheTest {
 @Rule public TemporaryFolder folder=new TemporaryFolder();
 static final String SHA="961d5ff98a17f4aa6de69864d0aa71fa5bac682301d2b5d17a3f24c5c99a46d4";
 String sha(byte[] b)throws Exception{StringBuilder s=new StringBuilder();for(byte n:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",n&255));return s.toString();}
 @Test public void removesOnlyCompleteVerifiedModelAndPreservesNeighbouringFiles()throws Exception{Path cache=folder.newFolder().toPath();Path root=Files.createDirectories(cache.resolve("dictation-models/ru-0.22-"+SHA.substring(0,12)));Path model=Files.createDirectories(root.resolve("vosk-model-small-ru-0.22/am"));byte[] b={1,2,3};Files.write(model.resolve("final.mdl"),b);Files.write(root.resolve("ready.sha256"),SHA.getBytes(java.nio.charset.StandardCharsets.US_ASCII));Files.write(cache.resolve("draft"),new byte[]{4});RetiredModelData.removeVerifiedDictation(cache.toFile(),Collections.singletonMap("vosk-model-small-ru-0.22/am/final.mdl",sha(b)));assertFalse(Files.exists(root));assertTrue(Files.exists(cache.resolve("draft")));RetiredModelData.removeVerifiedDictation(cache.toFile(),Collections.emptyMap());}
 @Test public void unexpectedAlteredAndLinkedFilesPreventAllDeletion()throws Exception{for(String kind:new String[]{"unknown","altered","link","directory"}){Path cache=folder.newFolder().toPath();Path root=Files.createDirectories(cache.resolve("dictation-models/ru-0.22-"+SHA.substring(0,12)));byte[] b={1};Files.write(root.resolve("model"),b);Files.write(root.resolve("ready.sha256"),SHA.getBytes(java.nio.charset.StandardCharsets.US_ASCII));if(kind.equals("unknown"))Files.write(root.resolve("mine"),b);if(kind.equals("altered"))Files.write(root.resolve("model"),new byte[]{2});if(kind.equals("link")){Files.delete(root.resolve("model"));Files.createSymbolicLink(root.resolve("model"),cache.resolve("outside"));Files.write(cache.resolve("outside"),b);}if(kind.equals("directory"))Files.createDirectory(root.resolve("mine"));RetiredModelData.removeVerifiedDictation(cache.toFile(),Collections.singletonMap("model",sha(b)));assertTrue(kind,Files.exists(root.resolve("ready.sha256")));assertTrue(Files.exists(root.resolve("model")));}}
}
